 "content": "from collections import deque


def transform(grid):
    """Count T tetrominoes by stem orientation, then encode counts as corner pips."""
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            min_r = min(x for x, _ in cells)
            max_r = max(x for x, _ in cells)
            rows = {}
            for x, y in cells:
                rows.setdefault(x, []).append(y)
            if len(cells) == 4 and max_r - min_r == 1 and sorted(len(v) for v in rows.values()) == [1, 3]:
                if len(rows[min_r]) == 1:
                    up += 1
                else:
                    down += 1
    out = [[0] * 6 for _ in range(3)]
    pip_positions = ((0, 0), (0, 2), (2, 0), (2, 2))
    for count, color, offset in ((up, 3, 0), (down, 1, 3)):
        for i, (r, c) in enumerate(pip_positions[:min(count, 4)]):
            out[r][c + offset] = color
    return out


if __name__ == '__main__':
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))
